import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The rates for each grade on a sheet, each from its from-date. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * A grade's rate as shown: its from-date (null: from the beginning of time), a percent with two decimals,
     * and how many versions it has had.
     */
    public record RateView(String grade, LocalDate from, LocalDate to, String pct, int version) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getFromDate(), rate.getToDate(),
                    rate.getPct().setScale(2, RoundingMode.HALF_UP).toPlainString(), rate.getVersion());
        }
    }

    /**
     * A percent is 0.00 or more with up to two decimals; a blank from-date applies from the beginning of
     * time, a blank to-date has no end, and a to-date is not before the from-date.
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from,
            LocalDate to) {

        @AssertTrue
        public boolean isEndAfterStart() {
            return from == null || to == null || !to.isBefore(from);
        }
    }

    /** A rate preview as shown: how many claims' dues would differ, and the sum of the differences (two decimals). */
    public record PreviewView(int count, String diff) {
    }

    /** Pasted lines of {@code grade,rate,from,to}. */
    public record ImportForm(@NotNull @Size(max = 100_000) String text) {
    }

    /** How many rates an import set. */
    public record ImportView(int set) {
    }

    private final RateService service;
    private final RatePreviewService previews;
    private final RateImportService imports;

    public RateController(RateService service, RatePreviewService previews, RateImportService imports) {
        this.service = service;
        this.previews = previews;
        this.imports = imports;
    }

    /** What the candidate percent would do to the dues of the grade's OPEN and PENDING claims; nothing is saved. */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct) {
        RatePreviewService.Preview p = previews.preview(sheetId.trim(), grade, new BigDecimal(pct));
        return new PreviewView(p.count(), p.diff().toPlainString());
    }

    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(RateView::of).toList();
    }

    /**
     * The rates of the sheet's parent sheets, nearest first, up to three levels up: a grade with no rate in
     * force on the sheet takes the first of them that has one.
     */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.inherited(sheetId.trim()).stream().map(rs -> rs.stream().map(RateView::of).toList()).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @RequestHeader("X-User") @NotBlank String user,
            @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, form.from(), form.to(), new BigDecimal(form.pct())));
    }

    /** Set a rate per pasted line, in order, as the rate form sets it; one refused line sets none. */
    @PostMapping("/import")
    public ImportView importRates(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody ImportForm form) {
        return new ImportView(imports.importRates(sheetId.trim(), user.trim(), form.text()));
    }

    /** Another user set the same grade's rate for the same from-date at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void rateTaken() {
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Import rates: lines of {@code grade,rate,from,to} (from and to may be left out or blank). Every line is first
 * held to the rate form's rules, and the whole import is one change: a refused line sets nothing. Otherwise each
 * line is set in order exactly as the rate form sets it, replacing a rate for the same grade and from-date.
 */
@Service
public class RateImportService {

    private static final Pattern GRADE = Pattern.compile("[ABC]");
    private static final Pattern PCT = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");

    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private final RateService service;
    private final SheetRepository sheetRows;

    public RateImportService(RateService service, SheetRepository sheetRows) {
        this.service = service;
        this.sheetRows = sheetRows;
    }

    /** Set a rate per line, in order; returns how many were set. */
    @Transactional
    public int importRates(String sheetId, String user, String text) {
        sheetRows.lockById(sheetId);
        List<Line> lines = new ArrayList<>();
        for (String raw : text.split("\\R")) {
            if (raw.isBlank()) continue;
            lines.add(parse(raw));
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
        }
        for (Line line : lines) {
            service.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct());
        }
        return lines.size();
    }

    private static Line parse(String raw) {
        String[] f = raw.split(",", -1);
        if (f.length < 2 || f.length > 4) throw refused(raw, "give a grade, a rate, and optionally a from- and to-date");
        String grade = f[0].trim();
        if (!GRADE.matcher(grade).matches()) throw refused(raw, "the grade must be A, B or C");
        String pct = f[1].trim();
        if (!PCT.matcher(pct).matches()) throw refused(raw, "the rate must be 0.00 or more, with up to two decimals");
        LocalDate from = f.length > 2 ? date(raw, f[2], "from-date") : null;
        LocalDate to = f.length > 3 ? date(raw, f[3], "to-date") : null;
        if (from != null && to != null && to.isBefore(from)) throw refused(raw, "the to-date is before the from-date");
        return new Line(grade, new BigDecimal(pct), from, to);
    }

    private static LocalDate date(String raw, String field, String what) {
        if (field.isBlank()) return null;
        try {
            return LocalDate.parse(field.trim());
        } catch (DateTimeParseException e) {
            throw refused(raw, "the " + what + " must be a date (yyyy-mm-dd)");
        }
    }

    private static ResponseStatusException refused(String line, String why) {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Line \"" + line + "\": " + why);
    }
}
package net.officefloor.hq.app.rate;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.sheet.DatedSettings;
import net.officefloor.hq.app.sheet.SheetSettingRepository;
import org.springframework.stereotype.Service;

/**
 * The rates of a sheet's parent sheets, nearest first, up to {@link RateTable#ANCESTOR_LEVELS} levels up:
 * a grade with no rate in force on the sheet takes the first of them that has one. Reads the store directly,
 * within the caller's own transaction.
 */
@Service
public class ParentRates {

    private final SheetSettingRepository settings;
    private final RateRepository rates;

    public ParentRates(SheetSettingRepository settings, RateRepository rates) {
        this.settings = settings;
        this.rates = rates;
    }

    /** The rates of the sheet's parent, its parent's parent, and so on up to three levels. */
    public List<List<Rate>> of(String sheetId) {
        return from(sheetId, new DatedSettings(settings.findBySheetId(sheetId)).parent());
    }

    /** The rates of the parent given (null: none), then its own parents, for the sheet given. */
    public List<List<Rate>> from(String sheetId, String parent) {
        List<List<Rate>> found = new ArrayList<>();
        Set<String> seen = new HashSet<>(List.of(sheetId));
        while (parent != null && found.size() < RateTable.ANCESTOR_LEVELS && seen.add(parent)) {
            found.add(rates.findBySheetId(parent));
            parent = new DatedSettings(settings.findBySheetId(parent)).parent();
        }
        return found;
    }
}
